     1→{% load shared %}
     2→{% htmlmin %}
     3→  <div class="tag-cloud">
     4→    {% if tag_cloud.has_selected_tags %}
     5→      <p class="selected-tags">
     6→        {% for tag in tag_cloud.selected_tags %}
     7→          <a href="?{% remove_tag_from_query tag.name %}"
     8→             class="text-bold mr-2">
     9→            <span>-{{ tag.name }}</span>
    10→          </a>
    11→        {% endfor %}
    12→      </p>
    13→    {% endif %}
    14→    <div class="unselected-tags">
    15→      {% for group in tag_cloud.groups %}
    16→        <p class="group">
    17→          {% for tag in group.tags %}
    18→            {# Highlight first char of first tag in group #}
    19→            {% if forloop.counter == 1 %}
    20→              <a href="?{% add_tag_to_query tag.name %}"
    21→                 class="mr-2" data-is-tag-item>
    22→                <span
    23→                    class="highlight-char">{{ tag.name|first_char }}</span><span>{{ tag.name|remaining_chars:1 }}</span>
    24→              </a>
    25→            {% else %}
    26→              {# Render remaining tags normally #}
    27→              <a href="?{% add_tag_to_query tag.name %}"
    28→                 class="mr-2" data-is-tag-item>
    29→                <span>{{ tag.name }}</span>
    30→              </a>
    31→            {% endif %}
    32→          {% endfor %}
    33→        </p>
    34→      {% endfor %}
    35→    </div>
    36→  </div>
    37→{% endhtmlmin %}
